UPDATE menu_items SET description = 'Naoko is a vivid green cocktail that conceals a quiet melancholy beneath its brightness. It opens crisp, fresh, and almost carefree before unfolding into delicate floral notes and a lingering bittersweet finish. Crafted with Midori, blue agave tequila, chrysanthemum liqueur, lime, green apple infused with fresh orange peel, cucumber, and mint, it is inspired by Haruki Murakami’s Norwegian Wood. Gentle yet fragile, understated yet unforgettable, Naoko reveals her true depth slowly—inviting you to linger, sip by sip, until the final notes are all that remain.', ingredients = '["Mexicat Tequila","Green Fanta (preferably zero sugar)","Midori Melon Liqueur","Chrysanthemum Liqueur","Lime Juice","Saline solution","Keto Green Apple Syrup","Fresh Cucumbers","Fresh Orange Peels","Fresh Mint leaves"]' WHERE code = 'naoko';
